<?php require 'config.php'; require_login();$p=db();$rows=$p->query("SELECT * FROM tasks ORDER BY id")->fetchAll();$total=count($rows);$running=0;$done=0;$red=0;$yellow=0;$green=0;$over=0;$sum=0;$n=0;$up=[];foreach($rows as $r){$c=calc($r);if(($r['status']??'')==='En curso')$running++;if(in_array($r['status']??'',array('Terminada','Completada'),true))$done++;if($c['light']==='ROJO')$red++;elseif($c['light']==='AMARILLO')$yellow++;else $green++;if($c['remaining']!==null&&$c['remaining']<0)$over++;if($r['level']==='PROCESO'){$sum+=$c['progress'];$n++;}if($r['end_date']&&!in_array($r['status']??'',array('Terminada','Completada'),true))$up[]=array($r,$c);}usort($up,function($a,$b){return strcmp($a[0]['end_date'],$b[0]['end_date']);});$avg=$n?(int)round($sum/$n):0;require 'header.php';?>
<div class="page-title"><div><h1>Dashboard de gestión</h1><p>Resumen ejecutivo del plan de trabajo y sus alertas.</p></div><a class="btn primary" href="task_form.php?level=PROCESO">＋ Nuevo proceso</a></div>
<div class="kpis"><div class="kpi"><span>Total registros</span><b><?=$total?></b><small>Procesos y etapas</small></div><div class="kpi blue"><span>En curso</span><b><?=$running?></b><small>Trabajo activo</small></div><div class="kpi green"><span>Terminadas</span><b><?=$done?></b><small>Registros cerrados</small></div><div class="kpi red"><span>Alertas rojas</span><b><?=$red?></b><small>Requieren atención</small></div></div>
<div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>Indicadores</h2><a href="tasks.php">Ver plan</a></div><div class="metric-list"><div><span>Avance promedio de procesos</span><strong><?=$avg?>%</strong></div><div class="big-progress"><i style="width:<?=$avg?>%"></i></div><div><span>Tareas atrasadas</span><strong><?=$over?></strong></div><div><span>Semáforo amarillo</span><strong><?=$yellow?></strong></div><div><span>Semáforo verde</span><strong><?=$green?></strong></div></div></section><section class="panel"><div class="panel-head"><h2>Alertas ejecutivas</h2></div><div class="alert-cards"><a href="tasks.php"><i class="traffic rojo"></i><span>ROJO</span><b><?=$red?></b></a><a href="tasks.php"><i class="traffic amarillo"></i><span>AMARILLO</span><b><?=$yellow?></b></a><a href="tasks.php"><i class="traffic verde"></i><span>VERDE</span><b><?=$green?></b></a></div></section></div>
<section class="panel"><div class="panel-head"><h2>Próximos vencimientos</h2><a href="tasks.php">Abrir plan de tareas</a></div><div class="mini-table"><table><thead><tr><th>ID</th><th>Tarea</th><th>Responsable</th><th>Fecha término</th><th>Alerta</th></tr></thead><tbody><?php $i=0;foreach($up as $u):if($i++>=6)break;$r=$u[0];$c=$u[1];?><tr><td><?=h($r['code'])?></td><td><?=h($r['task'])?></td><td><?=h($r['responsible']?:'—')?></td><td><?=h($r['end_date'])?></td><td><span class="alert <?=strtolower($c['light'])?>"><?=h($c['alert'])?></span></td></tr><?php endforeach;?><?php if(!$up):?><tr><td colspan="5" class="empty">No hay vencimientos pendientes.</td></tr><?php endif;?></tbody></table></div></section>
<?php require 'footer.php';?>